INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (3,'SELECT','EXPL par section / propriétaire',0x73656C656374206578706C5F6964206173206F626A6563745F69642C20274558504C27206173206F626A6563745F747970652066726F6D206578656D706C6169726573207768657265206578706C5F73656374696F6E20696E2028212173656374696F6E21212920616E64206578706C5F6F776E65723D212170726F7072696F2121,'Sélection d\'exemplaires par section par propriétaire','1 2',0,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<FIELDS>\n <FIELD NAME=\"section\" MANDATORY=\"yes\">\n  <ALIAS><![CDATA[Section]]></ALIAS>\n  <TYPE>query_list</TYPE>\n<OPTIONS FOR=\"query_list\">\r\n <QUERY><![CDATA[select idsection, section_libelle from docs_section order by section_libelle]]></QUERY>\r\n <MULTIPLE>yes</MULTIPLE>\r\n <UNSELECT_ITEM VALUE=\"\"><![CDATA[]]></UNSELECT_ITEM>\r\n</OPTIONS>\n </FIELD>\n <FIELD NAME=\"proprio\" MANDATORY=\"yes\">\n  <ALIAS><![CDATA[Propriétaire]]></ALIAS>\n  <TYPE>query_list</TYPE>\n<OPTIONS FOR=\"query_list\">\r\n <QUERY>select idlender, lender_libelle from lenders order by lender_libelle</QUERY>\r\n <MULTIPLE>no</MULTIPLE>\r\n <UNSELECT_ITEM VALUE=\"\"></UNSELECT_ITEM>\r\n</OPTIONS>\n </FIELD>\n</FIELDS>');
