INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (20,'ACTION','Changement du code statistique d\'exemplaires',0x757064617465206578656D706C616972657320736574206578706C5F636F6465737461743D21216E6F75766561755F636F6465737461742121207768657265206578706C5F696420696E2028434144444945284558504C2929,'','1',0,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<FIELDS>\n <FIELD NAME=\"nouveau_codestat\" MANDATORY=\"yes\">\n  <ALIAS><![CDATA[Nouveau code statistique]]></ALIAS>\n  <TYPE>query_list</TYPE>\n<OPTIONS FOR=\"query_list\">\r\n <QUERY><![CDATA[select idcode, codestat_libelle from docs_codestat order by codestat_libelle]]></QUERY>\r\n <MULTIPLE>no</MULTIPLE>\r\n <UNSELECT_ITEM VALUE=\"\"><![CDATA[]]></UNSELECT_ITEM>\r\n</OPTIONS>\n </FIELD>\n</FIELDS>');
INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (21,'ACTION','Changement de type de document des notices d\'un panier',0x757064617465206E6F74696365732073657420747970646F633D21216E65775F747970646F632121207768657265206E6F746963655F696420696E2028434144444945284E4F54492929,'','1',0,'<?xml version=\"1.0\" encoding=\"utf-8\"?><FIELDS><FIELD NAME=\"new_typdoc\" MANDATORY=\"yes\">\n<ALIAS><![CDATA[Nouveau type de document]]></ALIAS>\n<TYPE>list</TYPE>\n<OPTIONS FOR=\"list\">\n<ITEMS>\n<ITEM VALUE=\"b\">texte manuscrit</ITEM>\n<ITEM VALUE=\"c\">partition musicale imprimée</ITEM>\n<ITEM VALUE=\"d\">partition musicale manuscrite</ITEM>\n<ITEM VALUE=\"e\">document cartographique imprimé</ITEM>\n<ITEM VALUE=\"f\">document cartographique manuscrit</ITEM>\n<ITEM VALUE=\"g\">document projeté ou vidéo</ITEM>\n<ITEM VALUE=\"i\">enregistrement sonore non musical</ITEM>\n<ITEM VALUE=\"j\">enregistrement sonore musical</ITEM>\n<ITEM VALUE=\"k\">document graphique à deux dimensions</ITEM>\n<ITEM VALUE=\"l\">document électronique</ITEM>\n<ITEM VALUE=\"m\">document multimédia</ITEM>\n<ITEM VALUE=\"r\">objet à 3 dimensions, artefacts, ...</ITEM>\n</ITEMS>\n<MULTIPLE>no</MULTIPLE>\n<UNSELECT_ITEM VALUE=\"a\">texte imprimé</UNSELECT_ITEM>\n</OPTIONS>\n</FIELD>\n</FIELDS>');
INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (22,'ACTION','Changement de message des exemplaires d\'un panier',0x757064617465206578656D706C616972657320736574206578706C5F6E6F74653D2721216E65775F6E6F7465212127207768657265206578706C5F696420696E2028434144444945284558504C2929,'','1',0,'<?xml version=\"1.0\" encoding=\"utf-8\"?><FIELDS><FIELD NAME=\"new_note\" MANDATORY=\"no\">\n<ALIAS><![CDATA[Nouveau message]]></ALIAS>\n<TYPE>text</TYPE>\n<OPTIONS FOR=\"text\">\n<SIZE>25</SIZE>\n<MAXSIZE>25</MAXSIZE>\n</OPTIONS>\n</FIELD>\n</FIELDS>');
