INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (24,'ACTION','Changement de propriétaire des exemplaires',0x757064617465206578656D706C616972657320736574206578706C5F6F776E65723D21216F776E65722121207768657265206578706C5F696420696E2028434144444945284558504C2929,'','1',0,'<?xml version=\"1.0\" encoding=\"utf-8\"?><FIELDS><FIELD NAME=\"owner\" MANDATORY=\"yes\">\n<ALIAS><![CDATA[propriétaire]]></ALIAS>\n<TYPE>query_list</TYPE>\n<OPTIONS FOR=\"query_list\">\n<QUERY>select idlender, lender_libelle from lenders order by lender_libelle</QUERY>\n<MULTIPLE>no</MULTIPLE>\n<UNSELECT_ITEM VALUE=\"\"></UNSELECT_ITEM>\n</OPTIONS>\n</FIELD>\n</FIELDS>');
