INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (2,'Lisez 5 fruits et légumes par jour !','Dans l\'assiette,<br />La courgette<br />C\'est ennuyant !<br />Mais dans les livres,<br />C\'est bien plus amusant !<br />','La bibliothèque vous propose :<br /><br /><blockquote>Une heure du conte potagère !<br /><br />Et des ateliers de création avec fruits et légumes du marché...<br /></blockquote>',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',5,6,'2012-10-25 00:00:00',0,'2012-10-24 22:00:00');
INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (3,'Fiction adultes','Découvrez les nouveautés du rayon adultes en romans, livres audio, BD<br />','<br />',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',7,2,'2012-10-25 00:00:00',0,'2012-10-24 22:00:00');
INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (4,'Poisson rouge','Le meilleur site de jeux en ligne pour les tout-petits !<br />','Fusce egestas vestibulum neque et faucibus. Integer commodo pretium \nporttitor. Phasellus varius dui at neque dignissim a fermentum magna \nluctus. Nulla facilisi. Cras erat nulla, ullamcorper in tincidunt eget, \ndignissim nec nisl. Nam ut dui nunc. Etiam in enim a sapien fermentum \naccumsan. <br /><br />Donec semper magna non tellus porttitor ultricies nec et \nlorem. Fusce ac felis odio. Cras eu urna nulla. Sed quis dignissim \nmagna. Praesent ultricies, dui et viverra facilisis, elit dui volutpat \narcu, venenatis malesuada justo velit a mi.\n',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',8,5,'2012-10-25 00:00:00',0,'2012-10-24 22:00:00');
INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (12,'Georges : petit-petit-petit magazine','Le concept de Georges :<br />\nBienvenue dans l\'univers de Georges, petit petit petit magazine, \nrevue alternative trimestrielle créée par les Éditions Grains de Sel, \npour les enfants ni trop petits ni trop grands.<br />','Mais qui est Georges ?<br />\n\nUn magazine décalé et exigeant qui stimule la curiosité et revisite les traitements traditionnels des magazines pour enfants.<br />\n\n<br />\n\nQuels sont ses atouts ?<br />\n\nUn graphisme épuré  et un thème original pour chaque numéro, sur un beau\n papier offset et recyclé, avec des illustrateurs aux univers sensibles \net un second degré qui séduit les enfants (et même leurs parents).<br />\n\n<br />\n\nComment se présente-t-il ?<br />\n\nPartie 1 : des HISTOIRES vraies, courtes, longues ou à l\'envers.<br />\n\nPartie 2 : des JEUX à colorier, calculer ou déchiffrer autour du thème du numéro.<br />\n\nPartie 3 : des RUBRIQUES-À-BRAC pour découvrir des métiers, langues \nétrangères, scènes de films ou expériences scientifiques, mais de façon \ntoujours farfelue !',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',8,5,'2012-10-26 00:00:00',0,'2012-10-25 22:00:00');
INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (17,'Des bibliothèques pleines de fantômes','Avez-vous peur de mourir dans votre sommeil, enseveli sous l\'écroulement\n de votre bibliothèque ? Classez-vous les volumes par \nthème, langue, auteur, date de parution, format ou selon un autre \ncritère de vous seul connu ?','Autant de graves questions se posant à cette espèce en voie de \ndisparition : les bibliomanes, qui, outre la passion de posséder les \nlivres, ont celle de les lire. Les bibliothèques sont des êtres vivants à\n l\'image de notre complexité intérieure. Elles finissent par composer un\n labyrinthe dont pour notre plus grand, et dangereux, plaisir nous \npouvons très bien ne plus sortir. Dans ce petit traité sur l\'art de \nvivre avec trop de livres apparaissent, parmi nombre d\'autres, Pessoa \ntentant de devenir bibliothécaire, Matisse postulant au poste de \n«contrôleur du droit des pauvres» ou encore le capitaine Achab et le \nmystère de sa jambe abandonnée à Moby Dick. En fait, ces milliers de \npages qui occupent nos étagères sont peuplées de fantômes bien vivants \nqui, une fois rencontrés, ne nous quittent plus.',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',8,5,'2012-10-26 00:00:00',0,'2012-10-25 22:00:00');
INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (18,'Les annales du disque-monde','\n      Le disque-monde est plat, porté par quatre éléphants debout sur le dos\n d\'une tortue naviguant dans le cosmos. Tout le monde le sait et \nquoiqu\'en disent certaines sectes, c\'est la vérité. <br />','<p>Les héros de ce monde sont à son image : atypiques.<br /> Rincevent, \nmagicien malchanceux froussard et raté, ne connaît qu\'un seul sort mais \nil n\'ose pas le lancer car il pourrait tout détruire.<br /> Mémé \nCiredutemps, sorcière d\'un certain âge, ne peut que diriger tous ceux \nqui l\'entourent, elle ne fait d\'ailleurs que très rarement usage de sa \nmagie car tout le monde la connaît et lui obéit.<br /> La Mort, la faucheuse avec son grand suaire et sa faux bien aiguisée, grande humaniste incomprise.  </p>Pratchett\n consacre chacun de ses romans à un de ces personnages même s\'il arrive \nqu\'ils se rencontrent de temps en temps, car tout est possible dans cet \nunivers totalement fou et plein d\'humour !<br />',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',8,5,'2012-10-26 00:00:00',0,'2012-10-25 22:00:00');
