INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (12,'article',1,0,0,'Georges : petit-petit-petit magazine',130,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (12,'article',2,0,0,'Le concept de Georges : \nBienvenue dans l\'univers de Georges, petit petit petit magazine, \nrevue alternative trimestrielle créée par les Éditions Grains de Sel, \npour les enfants ni trop petits ni trop grands.',100,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (12,'article',3,0,0,'Mais qui est Georges ? \n\nUn magazine décalé et exigeant qui stimule la curiosité et revisite les traitements traditionnels des magazines pour enfants. \n\n \n\nQuels sont ses atouts ? \n\nUn graphisme épuré  et un thème original pour chaque numéro, sur un beau\n papier offset et recyclé, avec des illustrateurs aux univers sensibles \net un second degré qui séduit les enfants (et même leurs parents). \n\n \n\nComment se présente-t-il ? \n\nPartie 1 : des HISTOIRES vraies, courtes, longues ou à l\'envers. \n\nPartie 2 : des JEUX à colorier, calculer ou déchiffrer autour du thème du numéro. \n\nPartie 3 : des RUBRIQUES-À-BRAC pour découvrir des métiers, langues \nétrangères, scènes de films ou expériences scientifiques, mais de façon \ntoujours farfelue !',100,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (12,'article',7,0,0,'0000-00-00 00:00:00',100,'');
