INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (17,'article',1,0,0,'Des bibliothèques pleines de fantômes',130,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (17,'article',2,0,0,'Avez-vous peur de mourir dans votre sommeil, enseveli sous l\'écroulement\n de votre bibliothèque ? Classez-vous les volumes par \nthème, langue, auteur, date de parution, format ou selon un autre \ncritère de vous seul connu ?',100,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (17,'article',3,0,0,'Autant de graves questions se posant à cette espèce en voie de \ndisparition : les bibliomanes, qui, outre la passion de posséder les \nlivres, ont celle de les lire. Les bibliothèques sont des êtres vivants à\n l\'image de notre complexité intérieure. Elles finissent par composer un\n labyrinthe dont pour notre plus grand, et dangereux, plaisir nous \npouvons très bien ne plus sortir. Dans ce petit traité sur l\'art de \nvivre avec trop de livres apparaissent, parmi nombre d\'autres, Pessoa \ntentant de devenir bibliothécaire, Matisse postulant au poste de \n«contrôleur du droit des pauvres» ou encore le capitaine Achab et le \nmystère de sa jambe abandonnée à Moby Dick. En fait, ces milliers de \npages qui occupent nos étagères sont peuplées de fantômes bien vivants \nqui, une fois rencontrés, ne nous quittent plus.',100,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (17,'article',7,0,0,'0000-00-00 00:00:00',100,'');
