INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (18,'article',1,0,0,'Les annales du disque-monde',130,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (18,'article',2,0,0,'Le disque-monde est plat, porté par quatre éléphants debout sur le dos\n d\'une tortue naviguant dans le cosmos. Tout le monde le sait et \nquoiqu\'en disent certaines sectes, c\'est la vérité.',100,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (18,'article',3,0,0,'Les héros de ce monde sont à son image : atypiques.  Rincevent, \nmagicien malchanceux froussard et raté, ne connaît qu\'un seul sort mais \nil n\'ose pas le lancer car il pourrait tout détruire.  Mémé \nCiredutemps, sorcière d\'un certain âge, ne peut que diriger tous ceux \nqui l\'entourent, elle ne fait d\'ailleurs que très rarement usage de sa \nmagie car tout le monde la connaît et lui obéit.  La Mort, la faucheuse avec son grand suaire et sa faux bien aiguisée, grande humaniste incomprise.   Pratchett\n consacre chacun de ses romans à un de ces personnages même s\'il arrive \nqu\'ils se rencontrent de temps en temps, car tout est possible dans cet \nunivers totalement fou et plein d\'humour !',100,'');
INSERT INTO cms_editorial_fields_global_index (num_obj, type, code_champ, code_ss_champ, ordre, value, pond, lang) VALUES (18,'article',7,0,0,'0000-00-00 00:00:00',100,'');
