INSERT INTO cms_managed_modules (managed_module_name, managed_module_box) VALUES ('cms_module_agenda','a:2:{s:6:\"module\";a:1:{s:9:\"calendars\";a:2:{s:9:\"calendar1\";a:5:{s:4:\"name\";s:4:\"Expo\";s:5:\"color\";s:7:\"#D6DE39\";s:4:\"type\";s:1:\"3\";s:10:\"start_date\";s:1:\"2\";s:8:\"end_date\";s:1:\"3\";}s:9:\"calendar2\";a:5:{s:4:\"name\";s:10:\"Evénement\";s:5:\"color\";s:7:\"#F0A935\";s:4:\"type\";s:1:\"6\";s:10:\"start_date\";s:1:\"5\";s:8:\"end_date\";s:1:\"0\";}}}s:5:\"views\";a:1:{s:33:\"cms_module_agenda_view_eventslist\";a:1:{s:9:\"templates\";a:1:{s:9:\"template1\";a:2:{s:4:\"name\";s:58:\"Affichage d\'une liste d\'événements à partir de l\'agenda\";s:7:\"content\";s:530:\"<div>\r\n{% for event in events %}\r\n<h3>\r\n{% if event.event_start.format_value %}\r\n {% if event.event_end.format_value %}\r\nDu {{event.event_start.format_value}} au {{event.event_end.format_value}}\r\n {% else %}\r\nLe {{event.event_start.format_value}}\r\n {% endif %}\r\n{% endif%} : {{event.title}}\r\n</h3>\r\n<blockquote>\r\n<a href=\'{{event.link}}\'><img style=\"float:left;margin-right:5px;\" src=\'{{event.logo.vign}}\'/></a>\r\n<p>{{event.resume}}</p>\r\n<br/>\r\n<div class=\"row\">{{event.content}}</div>\r\n</blockquote>\r\n<br />\r\n{% endfor %}\r\n</div>\";}}}}}');
