INSERT INTO cms_managed_modules (managed_module_name, managed_module_box) VALUES ('cms_module_section','a:1:{s:5:\"views\";a:1:{s:30:\"cms_module_common_view_section\";a:1:{s:9:\"templates\";a:1:{s:9:\"template1\";a:2:{s:4:\"name\";s:24:\"Affichage d\'une rubrique\";s:7:\"content\";s:755:\"<h2>{{title}}</h2>\r\n<img style=\"float:left;margin-right:5px;max-height:200px;max-width:200px;\" src=\'{{logo.large}}\' />\r\n<p>{{resume}}</p>\r\n<div class=\"row\">{{content}}</div>\r\n  <ul>\r\n   {% for child in children %}\r\n    <li><a href=\'{{child.link}}\'>{{child.title}}</a></li>\r\n   {% endfor %}\r\n  </ul>\r\n\r\n   {% for article in articles %}\r\n<div style=\"width:49%;margin-right:1%;float:left;margin-bottom:5px;margin-top:5px;\">\r\n<h3>{{article.title}}</h3>\r\n<a href=\'{{article.link}}\' alt=\'{{article.title}}\' title=\"{{article.title}}\"><img style=\"float:left;margin-right:5px;\" src=\'{{article.logo.vign}}\' /></a>\r\n<p>{{article.resume}}</p>\r\n<a style=\"text-align:right;\" href=\"{{article.link}}\">Lire la suite...</a>\r\n</div>\r\n   {% endfor %}\r\n<div class=\"row\"></div>\";}}}}}');
INSERT INTO cms_managed_modules (managed_module_name, managed_module_box) VALUES ('cms_module_article','a:1:{s:5:\"views\";a:1:{s:30:\"cms_module_common_view_article\";a:1:{s:9:\"templates\";a:1:{s:9:\"template1\";a:2:{s:4:\"name\";s:22:\"Affichage d\'un article\";s:7:\"content\";s:803:\"<h3>\r\n\r\n{% if fields_type.date_debut.values.0.value %}\r\n {% if fields_type.date_fin.values.0.value %}\r\nDu {{fields_type.date_debut.values.0.format_value}} au {{fields_type.date_fin.values.0.format_value}} : \r\n {% else %}\r\nLe {{fields_type.date_debut.values.0.format_value}} : \r\n {% endif %}\r\n{% endif%}\r\n{% if fields_type.date.values.0.value %}\r\nLe {{fields_type.date.values.0.format_value}} : \r\n{% endif%}\r\n\r\n{{title}}</h3>\r\n\r\n<img style=\"float:left;margin-right:5px;max-height:200px;max-width:200px;\" src=\'{{logo.large}}\' />\r\n\r\n<p>{{resume}}</p>\r\n<br />\r\n\r\n<div class=\"row\">{{content}}</div>\r\n<br />\r\n{% if fields_type.identifiant_notice.values.0.value %}\r\n<a href=\"./index.php?lvl=notice_display&id={{fields_type.identifiant_notice.values.0.value}}\">Voir le document dans le catalogue</a>\r\n{% endif%}\";}}}}}');
INSERT INTO cms_managed_modules (managed_module_name, managed_module_box) VALUES ('cms_module_articleslist','a:1:{s:5:\"views\";a:2:{s:35:\"cms_module_common_view_articleslist\";a:1:{s:9:\"templates\";a:4:{s:9:\"template1\";a:2:{s:4:\"name\";s:42:\"Liste d\'articles - sélections nouveautés\";s:7:\"content\";s:322:\"<h2>Nouveautés</h2>\r\n{% for article in articles %}\r\n<div style=\"width:49%;margin-right:1%;float:left;margin-bottom:5px;margin-top:5px;text-align:center;\">\r\n<a href=\"{{article.link}}\">\r\n<img style=\"width:90px;\" src=\'{{article.logo.large}}\'/>\r\n<h4>{{article.title}}</h4>\r\n</a>\r\n</div>\r\n{% endfor %}\r\n<div class=\"row\"></div>\";}s:9:\"template2\";a:2:{s:4:\"name\";s:16:\"Liste de brèves\";s:7:\"content\";s:146:\"<h2>Brèves</h2>\r\n<hr>\r\n{% for article in articles %}\r\n<h4>{{article.title}}</h4>\r\n<blockquote>{{article.resume}}</blockquote>\r\n<hr>\r\n{% endfor %}\";}s:9:\"template3\";a:2:{s:4:\"name\";s:48:\"Liste d\'articles - résultats recherche articles\";s:7:\"content\";s:659:\"<h3>Résultat de la recherche</h3>\r\n{% if articles %}\r\n   {% for article in articles %}\r\n<div style=\"width:49%;margin-right:1%;float:left;margin-bottom:5px;margin-top:5px;\">\r\n<h3>{{article.title}}</h3>\r\n<a href=\'{{article.link}}\' alt=\'{{article.title}}\' title=\"{{article.title}}\"><img style=\"float:left;margin-right:5px;\" src=\'{{article.logo.vign}}\' /></a>\r\n<p>{{article.resume}}</p>\r\n<a style=\"text-align:right;\" href=\"{{article.link}}\">Lire la suite...</a>\r\n</div>\r\n   {% endfor %}\r\n<div class=\"row\"></div>\r\n{% else %}\r\n<br />\r\nPas de résultats\r\n<br />\r\n<a href=\"./index.php?search_type_asked=simple_search\">>> Rechercher dans le catalogue</a>\r\n{% endif %}\";}s:9:\"template4\";a:2:{s:4:\"name\";s:49:\"Liste d\'articles - résultats recherche catalogue\";s:7:\"content\";s:509:\"{% if articles %}\r\n<h3>Lire aussi...</h3>\r\n{% endif %}\r\n   {% for article in articles %}\r\n<div style=\"width:49%;margin-right:1%;float:left;margin-bottom:5px;margin-top:5px;\">\r\n<h3>{{article.title}}</h3>\r\n<a href=\'{{article.link}}\' alt=\'{{article.title}}\' title=\"{{article.title}}\"><img style=\"float:left;margin-right:5px;\" src=\'{{article.logo.vign}}\' /></a>\r\n<p>{{article.resume}}</p>\r\n<a style=\"text-align:right;\" href=\"{{article.link}}\">Lire la suite...</a>\r\n</div>\r\n   {% endfor %}\r\n<div class=\"row\"></div>\";}}}s:37:\"cms_module_articleslist_view_carousel\";a:1:{s:9:\"templates\";a:1:{s:9:\"template1\";a:3:{s:4:\"name\";s:29:\"Actualités en page d\'accueil\";s:7:\"content\";s:462:\"<h2>Actualités</h2>\r\n<ul id=\'carousel_{{id}}\'>\r\n	{% for record in records %}\r\n		<li class=\'{{id}}_item\' style=\"height:200px\">\r\n<h3>{{record.title}}</h3>\r\n<a href=\'{{record.link}}\' alt=\'{{record.title}}\' title=\"{{record.title}}\"><img style=\"float:left;margin-right:5px;max-height:200px;max-width:200px;\" src=\'{{record.logo.large}}\' /></a>\r\n{{record.resume}}\r\n<a style=\"text-align:right;\" href=\"{{record.link}}\">Lire la suite...</a>\r\n		</li>\r\n	{% endfor %}\r\n</ul>\";s:3:\"css\";s:789:\"#{{identifiant_dom_du_cadre}} {\r\n	overflow : hidden;\r\n}\r\n		\r\n#{{identifiant_dom_du_cadre}} .bx-wrapper {\r\n	width : inherit !important;\r\n	height : inherit !important;\r\n}\r\n#{{identifiant_dom_du_cadre}} ul li {\r\n	text-align: center;\r\n}\r\n\r\n#{{identifiant_dom_du_cadre}} .bx-wrapper {\r\n	width : inherit !important;\r\n	height : inherit !important;\r\n}\r\n\r\n#{{identifiant_dom_du_cadre}} ul li a {\r\n	display: block;\r\n	width: 150px;\r\n	margin: 0 auto;\r\n	text-align: center;\r\n	text-decoration: none;\r\n}\r\n/* pour l\'image vide...*/\r\n#{{identifiant_dom_du_cadre}} .bx-wrapper ul li a img {\r\n	height: 145px;\r\n	background-repeat: no-repeat;\r\n	-moz-box-shadow: 1px 1px 2px #cccccc;\r\n    -o-box-shadow: 1px 1px 2px #cccccc;\r\n    -webkit-box-shadow: 1px 1px 2px #cccccc;\r\n    box-shadow: 1px 1px 2px #cccccc;\r\n}\";}}}}}');
