INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (68,'i','Les perles et autres contes','','','',0,'',13,0,4,0,'2012','','','978-2-07-013600-1','','','14 cm','','','','Le symbole mystérieux d\'un collier qui a une perle de trop. La réalité crue qui vient anéantir le rêve et le bonheur offerts à une jeune aristocrate insouciante. L\'aventure, dans le port d\'Anvers, d\'un écrivain malheureux, qui fuit sa propre vie... Tels sont les thèmes et les personnages de ces trois contes. Et à travers eux, Karen Blixen nous démontre que le conte est bien l\'instrument privilégié de l\'exploration des mystères de la personnalité. Le doux velours du timbre d\'Anne Brochet nous transporte dans l\'univers mystérieux des contes de Karen Blixen. Une lecture posée qui met en mouvement l\'imagination de l\'auditeur. L\'écoute en classe de ces CD est autorisée par l\'éditeur','','','Livres lus en format CD',0,'',' livres lus format cd ','m','0',6,'15,90 eur','','',' symbole mysterieux collier qui perle trop realite crue qui vient aneantir reve bonheur offerts jeune aristocrate insouciante aventure dans port anvers ecrivain malheureux qui fuit sa propre vie tels sont themes personnages ces trois contes travers eux karen blixen nous demontre que conte est bien instrument privilegie exploration mysteres personnalite doux velours timbre anne brochet nous transporte dans univers mysterieux contes karen blixen lecture posee qui met mouvement imagination auditeur ecoute classe ces cd est autorisee par editeur ',' perles autres contes ','  Les perles et autres contes   ',1,'','2012-10-24 14:42:49','2012-10-24 15:08:13','0','','2012-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
