INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (70,'a','Sagesse d\'Afrique','','','paysages et pensées',0,'',7,0,0,0,'2008','','','978-2-8100-0117-0','1 vol. (160 p.)','ill. en coul., couv. ill. en coul.','23 x 29 cm','','Contient diverses pensées, poèmes et proverbes de différents auteurs\r\nIndex','','Présentation de l\'éditeur\r\nL\'Afrique se dévoile, au fil de magnifiques photographies accompagnées de pensées, de poèmes et de proverbes emplis de philosophie, à l\'image de ce continent dont la beauté invite à la médiation. Un voyage en terre d\'émerveillement, guidé par le regard de nombreux écrivains et d\'hommes engagés, pour découvrir un espace fascinant, ses paysages, sa faune et ses habitants. ','','','Afrique;Photographies',97,'',' afrique photographies ','m','0',7,'19,90 EUR',' contient diverses pensees poemes proverbes differents auteurs index ','',' presentation editeur afrique se devoile fil magnifiques photographies accompagnees pensees poemes proverbes emplis philosophie image ce continent dont beaute invite mediation voyage terre emerveillement guide par regard nombreux ecrivains hommes engages pour decouvrir espace fascinant ses paysages sa faune ses habitants ',' sagesse afrique paysages pensees ','  Sagesse d\'Afrique   paysages et pensées',1,'','2012-10-24 14:42:49','2012-12-12 14:05:39','0','','2008-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (71,'a','Afriques','','','',0,'',8,0,0,0,'2012','','','978-2-7541-0611-5','1 vol. (non paginé [395] p.)','tout en ill., couv. ill.','28 cm','','','','Depuis plus de vingt ans Raymond Depardon a parcouru tout le continent africain auquel il a consacré plusieurs films. Il a réalisé ainsi une grande quantité de photographies dont 350 inédites sont présentées dans cet ouvrage. Ces photographies couvrent toute l\'Afrique, à travers une présentation non pas par pays mais par associations originales. Ces associations privilégient un rythme soutenu, sans temps d\'arrêt, des enchaînements qui montrent la vie au travers de sujets très variés : portraits, villes, paysages, religions, activités sociales et métiers mais aussi des conflits et la misère. A travers ses photographies, exemptes de toute volonté d\'esthétiser son propos, Raymond Depardon ne livre aucun jugement sur l\'Afrique, aucune thèse. Ce qui relie entre elles ces prises de vue, c\'est l\'impulsion de l\'?il, simplement un regard de photographe et de grand voyageur sur les paysages et les hommes qui peuplent ce continent. Pourquoi des Afriques ? Depuis 1960, année de ma première rencontre avec le continent africain à l\'âge de dix-huit ans, et jusqu\'à mon dernier voyage cet hiver au Horar, je n\'ai cessé de photographier l\'Afrique. Mais que de lieux, de temps différents ! Une vie toute entière ne suffirait pas à prétendre connaître cette Afrique. Aujourd\'hui, les prétextes, les raisons de ces voyages sont oubliés. C\'est pour cela que j\'avais envie de faire ce livre, pour rendre la liberté à toutes ces photographies et enfin réunir toutes ces Afriques, celles des pistes, des sourires, des famines et des guerres civiles. Je voulais oser ces quatre cents pages de photographies sous respiration. Je voulais étouffer devant l\'immense Afrique, me trouver comme au bord d\'une route où nous serions en panne pour plusieurs jours, envahis, à rester silencieux et à écouter. Je me souviens de chaque lieu, de chaque temps. J\'ose le désordre, il le faut. Je réunis ces photographies prises pendant quarante-cinq ans de voyages en Afrique. Raymond Depardon','','','Afrique;Photographies',97,'',' afrique photographies ','m','0',8,'25 EUR','','',' depuis plus vingt ans raymond depardon parcouru tout continent africain auquel il consacre plusieurs films il realise ainsi grande quantite photographies dont 350 inedites sont presentees dans cet ouvrage ces photographies couvrent toute afrique travers presentation non pas par pays mais par associations originales ces associations privilegient rythme soutenu sans temps arret enchainements qui montrent vie travers sujets tres varies portraits villes paysages religions activites sociales metiers mais aussi conflits misere travers ses photographies exemptes toute volonte esthetiser son propos raymond depardon ne livre aucun jugement sur afrique aucune these ce qui relie entre elles ces prises vue c est impulsion il simplement regard photographe grand voyageur sur paysages hommes qui peuplent ce continent pourquoi afriques depuis 1960 annee ma premiere rencontre avec continent africain age dix huit ans jusqu mon dernier voyage cet hiver horar je n ai cesse photographier afrique mais que lieux temps differents vie toute entiere ne suffirait pas pretendre connaitre cette afrique aujourd hui pretextes raisons ces voyages sont oublies c est pour cela que j avais envie faire ce livre pour rendre liberte toutes ces photographies enfin reunir toutes ces afriques celles pistes sourires famines guerres civiles je voulais oser ces quatre cents pages photographies sous respiration je voulais etouffer devant immense afrique me trouver comme bord route ou nous serions panne pour plusieurs jours envahis rester silencieux ecouter je me souviens chaque lieu chaque temps j ose desordre il faut je reunis ces photographies prises pendant quarante cinq ans voyages afrique raymond depardon ',' afriques ','  Afriques   ',1,'','2012-10-24 14:42:49','2012-10-24 14:11:40','0','','2012-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
