INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (76,'a','Aya de Yopougon','','','',1,'1',13,0,8,0,'2005','','','978-2-07-057311-0','1 vol. (96-[6] p.)','ill. en noir et en coul., couv. ill. en coul.','25 cm','','','','Côte d\'Ivoire, 1978. Aya, dix-neuf ans, vit à Yopougon, un quartier populaire d\'Abidjan. Ça sent le début des vacances mais très vite les choses vont commencer à se gâter…«Dans les années 1970, la vie était douce en Côte d’Ivoire. Il y avait du travail, les hôpitaux étaient équipés et l’école était obligatoire. J’ai eu la chance de connaître cette époque insouciante, où les jeunes n’avaient pas à choisir leur camp trop vite, et ne se préoccupaient que de la vie courante : les études, les parents, les amours… Et c’est cela que je veux raconter dans \"Aya\", cette Afrique qui subsiste malgré tout car, comme on dit chez nous, «la vie continue»…» (Marguerite Abouet)','','','',0,' aya yopougon ','','m','0',7,'15 EUR','','',' cote ivoire 1978 aya dix neuf ans vit yopougon quartier populaire abidjan ca sent debut vacances mais tres vite choses vont commencer se gater dans annees 1970 vie etait douce cote ivoire il y avait travail hopitaux etaient equipes ecole etait obligatoire j ai eu chance connaitre cette epoque insouciante ou jeunes n avaient pas choisir leur camp trop vite ne se preoccupaient que vie courante etudes parents amours c est cela que je veux raconter dans aya cette afrique qui subsiste malgre tout car comme on dit chez nous vie continue marguerite abouet ',' aya yopougon 1 aya yopougon ',' aya yopougon  1 Aya de Yopougon   ',1,'','2012-10-24 14:42:50','2012-12-12 14:12:28','0','','2005-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (77,'a','African psycho','','','roman',0,'',14,0,0,0,'2003','','','978-2-84261-438-6','190 p.','','21 cm','','','','Quatrième de couverture\r\n« Que les choses soient claires : je ne souhaite pas être plus grand que l’Angoualima, ni me greffer des petits doigts, je veux être apprécié en fonction du résultat de mon geste criminel. Ne pouvant égaler les prouesses du Grand Maître, j\'aimerais au moins être considéré comme son fils spirituel. Pour cela, j\'en suis conscient, je dois encore travailler : tuer Germaine ce 29 décembre, c\'est-à-dire dans deux jours, n\'est qu\'une étape vers ce couronnement. »\r\n\r\nGrégoire Nakobomayo, orphelin, a grandi dans une ville industrielle de l\'Afrique post-coloniale. Accueilli quelque temps chez un couple instruit, il reçoit une éducation bourgeoise jusqu\'au jour où il plante son crayon dans l\'oeil du fils unique qui cherche à le violer. Obligé de fuir, il se réfugie dans le quartier le plus délabré de la ville et prend pour modèle \"Angoualima\", le célèbre serial killer qui depuis des années défie le pays, ses juges, ses flics et ses journalistes. Mais n\'est pas serial killer qui veut\r\nAvec humour -et.ironie-Alain Mabanckou conte les déboires d\'un psychopathe velléitaire et sans talent qui cherche dans la perversité un sens à sa vie.','','','',0,'','','m','0',8,'','','',' quatrieme couverture que choses soient claires je ne souhaite pas etre plus grand que angoualima ni me greffer petits doigts je veux etre apprecie fonction resultat mon geste criminel ne pouvant egaler prouesses grand maitre j aimerais moins etre considere comme son fils spirituel pour cela j suis conscient je dois encore travailler tuer germaine ce 29 decembre c est dire dans deux jours n est qu etape vers ce couronnement gregoire nakobomayo orphelin grandi dans ville industrielle afrique post coloniale accueilli quelque temps chez couple instruit il recoit education bourgeoise jusqu jour ou il plante son crayon dans oeil fils unique qui cherche violer oblige fuir il se refugie dans quartier plus delabre ville prend pour modele angoualima celebre serial killer qui depuis annees defie pays ses juges ses flics ses journalistes mais n est pas serial killer qui veut avec humour ironie alain mabanckou conte deboires psychopathe velleitaire sans talent qui cherche dans perversite sens sa vie ',' african psycho roman ','  African psycho   roman',1,'','2012-10-24 14:42:50','2012-12-12 12:23:20','0','','2003-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (78,'a','Soleil noir','','','',0,'',15,0,9,0,'2012','','','978-2-36413-008-1','1 vol. (172 p.)','','21 cm','','','','Présentation de l\'éditeur\r\nIl y eut un long il était une fois…\r\nD’une écriture libre, anarchiste, de la même veine qu’un chant de Joyce où la structure vole en éclat…\r\nIl était une fois, un jeune narrateur, qu’importe son nom, pendu par les pieds par un chef aussi noir que les origines de l’homme, tiraillé par la faim et qui rêve de Blanche Goodfather en train de se baigner nue du côté des Chutes du Rocher. Fin…\r\nIl était une fois un amour magnifique, Marie, aveugle, comme seul personnage lucide parmi ceux qui sont pris au piège de la violence et de l’absurdité d’un pays sous apartheid… De jeunes gens dans l’émeute, émeute du langage, émeute de la pensée, émeute du regard sur le monde, sur la vie, contre un système…\r\nSoleil noir (écrit en 1980) est ce roman éclaté où l’auteur balaie d’un revers de la main la frontière entre le réel et l’irréel, entre le conte et le témoignage, entre le rêve et la pensée, nous propulsant littéralement sans un monde aveuglé que seul le dérèglement du langage peut appréhender. Roman de la révolte, Soleil noir, publié pour la première fois en français, est un roman mythique de Marechera, écrit entre la rue et de fréquents séjours en prison. ','','','',0,'','','m','0',8,'14,40 EUR','','',' presentation editeur il y eut long il etait fois ecriture libre anarchiste meme veine qu chant joyce ou structure vole eclat il etait fois jeune narrateur qu importe son nom pendu par pieds par chef aussi noir que origines homme tiraille par faim qui reve blanche goodfather train se baigner nue cote chutes rocher fin il etait fois amour magnifique marie aveugle comme seul personnage lucide parmi ceux qui sont pris piege violence absurdite pays sous apartheid jeunes gens dans emeute emeute langage emeute pensee emeute regard sur monde sur vie contre systeme soleil noir ecrit 1980 est ce roman eclate ou auteur balaie revers main frontiere entre reel irreel entre conte temoignage entre reve pensee nous propulsant litteralement sans monde aveugle que seul dereglement langage peut apprehender roman revolte soleil noir publie pour premiere fois francais est roman mythique marechera ecrit entre rue frequents sejours prison ',' soleil noir ','  Soleil noir   ',1,'','2012-10-24 14:42:50','2012-12-12 14:07:58','0','','2012-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (79,'a','Les loups','','','',0,'',16,0,0,0,'2006','','','978-2-87767-470-6','1 vol. (non paginé [31] p.)','ill. en noir et en coul., jaquette ill. en coul.','27 cm','','','','Présentation de l\'éditeur\r\nC\'est l\'histoire d\'un lapin qui emprunte un ouvrage à la bibliothèque de son quartier, et qui découvre l\'extraordinaire, l\'incroyable pouvoir qu\'ont certains livres sur leur lecteur, parfois... ','','','',0,'','','m','0',7,'15 EUR','','',' presentation editeur c est histoire lapin qui emprunte ouvrage bibliotheque son quartier qui decouvre extraordinaire incroyable pouvoir qu ont certains livres sur leur lecteur parfois ',' loups ','  Les loups   ',1,'','2012-10-24 14:42:50','2012-12-12 13:59:43','0','','2006-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (80,'a','La bibliothécaire','','','',0,'',17,0,10,0,'2007','','','978-2-01-322406-2','192 p.','','17 cm','','','','Pourquoi la vielle dame qui habite en face de chez Guillaume écrit-elle très tard la nuit? Quelle est cette jeune fille qui ne sort de chez elle qu\'à le nuit tombée? Pour résoudre ces mystères, Guillaume se lance dans un fantastique voyage au pays des livres et de l\'écriture','','','Romans;Jeunesse;Littérature jeunesse;Albums;Jeunesse en format poche',0,'',' romans jeunesse litterature jeunesse albums jeunesse format poche ','m','0',6,'4,90 eur','','',' pourquoi vielle dame qui habite face chez guillaume ecrit elle tres tard nuit quelle est cette jeune fille qui ne sort chez elle qu nuit tombee pour resoudre ces mysteres guillaume se lance dans fantastique voyage pays livres ecriture ',' bibliothecaire ','  La bibliothécaire   ',1,'','2012-10-24 14:42:50','2012-10-24 14:01:02','0','','2007-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (81,'a','Jojo et le secret de la bibliothécaire','','','',2,'',18,0,0,0,'2006','','','978-2-87833-390-9','1 vol. (non paginé [30] p.)','ill. en coul., couv. ill. en coul.','20 cm','','','','La bibliothécaire a confié un terrible secret à Jojo et depuis, il n\'est plus le même...\r\nUne fiction pleine d\'humour sur l\'apprentissage de la lecture. A lire dès le CP.','','','',0,' jojo ','','m','0',7,'5,50 EUR','','',' bibliothecaire confie terrible secret jojo depuis il n est plus meme fiction pleine humour sur apprentissage lecture lire cp ',' jojo jojo secret bibliothecaire ',' jojo   Jojo et le secret de la bibliothécaire   ',1,'','2012-10-24 14:42:50','2012-10-24 13:59:22','0','','2006-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (82,'a','La sagesse du bibliothécaire','','','',0,'',19,0,12,0,'2004','','','978-2-915543-03-2','109 p.','couv. ill.','20 cm','','','','Présentation de l\'éditeur\r\nLe bibliothécaire aime les livres comme le marin aime la mer. Il n\'est pas nécessairement bon nageur mais il sait naviguer. L\'océan du savoir qui grise tous les savants, rend modeste le bibliothécaire. La bibliothèque est ce lieu indispensable où le savoir décante. Regardez comme cet océan furieux se calme dans la bibliothèque ! Le bibliothécaire sait lire les livres sans les ouvrir. Son regard transperce\r\nles couvertures. Il visite la page de titre, l\'auteur, les éditeurs, va directement au colophon, relève la date, le format,\r\nle nombre de pages, s\'attarde sur la table des matières, vérifie s\'il y a des index. Il évalue enfin sa robustesse et la qualité de son papier, celle de sa mise en page et de son impression.\r\nTout est dit. Si les auteurs savaient cela, ils feraient de faux livres uniquement pour les bibliothèques. ','','','Bibliothécaires;Déontologie;Travail',3,'',' bibliothecaires deontologie travail ','m','0',7,'12 EUR','','',' presentation editeur bibliothecaire aime livres comme marin aime mer il n est pas necessairement bon nageur mais il sait naviguer ocean savoir qui grise tous savants rend modeste bibliothecaire bibliotheque est ce lieu indispensable ou savoir decante regardez comme cet ocean furieux se calme dans bibliotheque bibliothecaire sait lire livres sans ouvrir son regard transperce couvertures il visite page titre auteur editeurs va directement colophon releve date format nombre pages s attarde sur table matieres verifie s il y index il evalue enfin sa robustesse qualite son papier celle sa mise page son impression tout est dit si auteurs savaient cela ils feraient faux livres uniquement pour bibliotheques ',' sagesse bibliothecaire ','  La sagesse du bibliothécaire   ',1,'','2012-10-24 14:42:50','2012-12-12 14:06:23','0','','2004-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (83,'a','Le métier de bibliothécaire','','','',0,'',20,0,13,0,'2010','','12e éd.','978-2-7654-0977-9','1 vol. (565 p.)','ill., couv. ill.','24 cm','','','','','','','Bibliothéconomie;France',3,'',' bibliotheconomie france ','m','0',7,'42 EUR','','','',' metier bibliothecaire ','  Le métier de bibliothécaire   ',1,'','2012-10-24 14:42:50','2012-10-24 13:57:45','0','','2010-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (121,'a','N° 403 - septembre 2012 - Numéro spécial Afrique',NULL,'','le réveil d\'un continent',0,'',0,0,0,0,'2012',NULL,'','','','','','','','LE MONDE QUI CHANGE\r\nLa mortalité infantile amorce son déclin.\r\n\r\nLES HÉROS D\'AUJOURD\'HUI\r\nMo Ibrahim, cinquante-trois pays dans son collimateur.\r\n\r\nLE GOÛT DE GEO\r\nLe yassa poulet, ou l’hospitalité sénégalaise.\r\n\r\nÉVASION - Namibie, la nouvelle arche de Noé\r\nDans des espaces gérés par les habitants, la faune sauvage s’est multipliée, les touristes affluent et les populations en tirent un revenu.\r\n\r\nMODES DE VIE\r\nAfrican Valley(s) - L’Afrique aussi voit naître ces lieux où les technologies boostent la croissance.\r\nCampus en ébullition - Démographie oblige, les étudiants se pressent dans les universités d’Afrique subsaharienne.\r\n\r\nENVIRONNEMENT\r\nCinq chantiers qui vont changer l’Afrique.\r\nDov Zerah - Les deux défis à relever.\r\n\r\nGÉOPOLITIQUE - Région des Grands Lacs : la poudrière magnifique\r\nC’est un territoire riche, mais marqué par des décennies de conflits. La paix et le développement y font aujourd’hui leur chemin.\r\n\r\nCARTE DÉTACHABLE - Le réveil de l\'Afrique\r\n\r\nLE BON PLAN - Le Cap des Capétoniens\r\n\r\nGÉOPOLITIQUE - L\'eldorado de l\'Afrique latine\r\nL’Angola vit un boom exceptionnel. Portugais, Brésiliens ou Chinois viennent y tenter leur chance.\r\n\r\nGRANDE SÉRIE \"LA FRANCE DES VILLAGES\" - La Bourgogne\r\nPanorama mensuel des pépites du terroir. ','','','','',0,'','','b','2',1,'','',' monde qui change mortalite infantile amorce son declin heros aujourd hui mo ibrahim cinquante trois pays dans son collimateur gout geo yassa poulet ou hospitalite senegalaise evasion namibie nouvelle arche noe dans espaces geres par habitants faune sauvage s est multipliee touristes affluent populations tirent revenu modes vie african valley s afrique aussi voit naitre ces lieux ou technologies boostent croissance campus ebullition demographie oblige etudiants se pressent dans universites afrique subsaharienne environnement cinq chantiers qui vont changer afrique dov zerah deux defis relever geopolitique region grands lacs poudriere magnifique c est territoire riche mais marque par decennies conflits paix developpement y font aujourd hui leur chemin carte detachable reveil afrique bon plan cap capetoniens geopolitique eldorado afrique latine angola vit boom exceptionnel portugais bresiliens ou chinois viennent y tenter leur chance grande serie france villages bourgogne panorama mensuel pepites terroir ','',' n 403 septembre 2012 numero special afrique reveil continent ','  N° 403 - septembre 2012 - Numéro spécial Afrique   le réveil d\'un continent',1,'','2012-10-24 17:23:16','2012-11-20 08:29:44','0',,'2012-09-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (84,'a','Les bibliothèques','','','',0,'',21,0,14,0,'2010','n° 944','12e éd. mise à jour','978-2-13-057064-6','1 vol. (127 p.)','couv. ill. en coul.','18 cm','','','','À la fois lieux de travail pour des recherches contemporaines et lieux de conservation d\'un patrimoine, les bibliothèques ont un rôle charnière entre le passé et le présent. Mais si leur mission demeure identique, les moyens mis à leur disposition, ainsi que les modes de consultation et d\'usage des livres, sont aujourd?hui en pleine mutation.\r\n\r\nCet ouvrage s\'assigne donc une double tâche : présenter l\'histoire des bibliothèques dans le monde occidental afin de comprendre l\'ampleur des changements qu?elles connaissent depuis un siècle, et donc les nouveaux enjeux culturels et économiques engendrés par de telles évolutions.\r\n\r\nDocteur en histoire, Denis Pallier est inspecteur général honoraire des bibliothèques.','','','Bibliothèques',3,'',' bibliotheques ','m','0',7,'9,00 EUR','','',' fois lieux travail pour recherches contemporaines lieux conservation patrimoine bibliotheques ont role charniere entre passe present mais si leur mission demeure identique moyens mis leur disposition ainsi que modes consultation usage livres sont aujourd hui pleine mutation cet ouvrage s assigne donc double tache presenter histoire bibliotheques dans monde occidental afin comprendre ampleur changements qu elles connaissent depuis siecle donc nouveaux enjeux culturels economiques engendres par telles evolutions docteur histoire denis pallier est inspecteur general honoraire bibliotheques ',' bibliotheques ','  Les bibliothèques   ',1,'','2012-10-24 14:42:51','2012-10-24 13:57:04','0','','2010-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (85,'a','Le grand amour du bibliothécaire','','','',0,'',22,0,0,0,'2005','','','978-2-203-12937-5','','','19 cm','','','','Présentation de l\'éditeur\r\nLes livres, ça fait désordre et ça prend la poussière, c\'est tout. Voilà ce que pense Fulbert le bibliothécaire. D\'ailleurs, il n\'y a qu\'un seul livre dans sa bibliothèque ! Mais voici qu\'arrive la ravissante Rose-Marie, assoiffée de lecture. Fulbert, ébloui et troublé, est bien désemparé. Il va falloir qu\'il trouve des livres, et vite ! ','','','Littérature jeunesse;BD, Mangas, Humour',0,'',' litterature jeunesse bd mangas humour ','m','0',6,'6,00 eur','','',' presentation editeur livres ca fait desordre ca prend poussiere c est tout voila ce que pense fulbert bibliothecaire ailleurs il n y qu seul livre dans sa bibliotheque mais voici qu arrive ravissante rose marie assoiffee lecture fulbert ebloui trouble est bien desempare il va falloir qu il trouve livres vite ',' grand amour bibliothecaire ','  Le grand amour du bibliothécaire   ',1,'','2012-10-24 14:42:51','2012-12-12 13:56:17','0','','2005-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (86,'a','Le bibliothécaire','','','',0,'',13,0,16,0,'2005','','','978-2-07-077327-5','1 vol. (450 p.)','couv. ill.','23 cm','','','','Travaillant dans une université huppée de Washington D.C, David Golberg devient, par le plus grand des hasards, le bibliothécaire privé d\'Alan Stowe. Vieil acariâtre multimillionnaire, industriel cynique et sans scrupules, Stowe est surtout le plus grand bailleur de fonds du parti républicain. Or, nous sommes justement en pleine élection présidentielle et l\'équipe du candidat sortant, un gosse de riche va-t-en-guerre, ancien alcoolique reconverti en fou de Dieu, voit d\'un mauvais ?il l\'arrivée de cet inconnu auprès d\'un homme aussi influent que Stowe. À peine Golberg a-t-il le temps de commencer le classement des papiers de l\'homme d\'affaires qu\'il se retrouve pris en chasse par des barbouzes de la Sécurité intérieure. Tandis que la candidate démocrate grignote son retard sur le Président et que le grand jour du vote se rapproche, David, aidé d\'une bande d\'amis, se voit contraint de trouver dans les documents de Stowe l\'information pour laquelle on veut le tuer... Après Reality Show, adapté au cinéma sous le titre Des hommes d\'influence avec Dustin Hoffman et Robert De Niro, Larry Beinhart fait un retour fracassant sur la scène littéraire, démontant pièce par pièce l\'administration Bush, sa manière de manipuler le public américain et l\'opinion mondiale en jouant avec des peurs et des fantasmes archaïques. Comme quoi les critiques les plus virulentes ne viennent pas toujours de la « vieille Europe »...','','','',0,'','','m','0',7,'24 EUR','','',' travaillant dans universite huppee washington c david golberg devient par plus grand hasards bibliothecaire prive alan stowe vieil acariatre multimillionnaire industriel cynique sans scrupules stowe est surtout plus grand bailleur fonds parti republicain or nous sommes justement pleine election presidentielle equipe candidat sortant gosse riche va guerre ancien alcoolique reconverti fou dieu voit mauvais il arrivee cet inconnu aupres homme aussi influent que stowe peine golberg il temps commencer classement papiers homme affaires qu il se retrouve pris chasse par barbouzes securite interieure tandis que candidate democrate grignote son retard sur president que grand jour vote se rapproche david aide bande amis se voit contraint trouver dans documents stowe information pour laquelle on veut tuer apres reality show adapte cinema sous titre hommes influence avec dustin hoffman robert niro larry beinhart fait retour fracassant sur scene litteraire demontant piece par piece administration bush sa maniere manipuler public americain opinion mondiale jouant avec peurs fantasmes archaiques comme quoi critiques plus virulentes ne viennent pas toujours vieille europe ',' bibliothecaire ','  Le bibliothécaire   ',1,'','2012-10-24 14:42:51','2012-10-24 13:54:29','0','','2005-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (87,'a','L\'enlèvement de la bibliothécaire','','','',0,'',23,0,17,0,'2002','189','','978-2-07-053882-9','56 p.','ill. en coul., couv. ill. en coul.','18 cm','','','','En kidnappant Mlle Labourdette, la ravissante bibliothécaire, le chef des brigands et ses quatre complices croient pouvoir obtenir de la municipalité une rançon rondelette. Mais c\'est compter sans le courage de la jeune fille, son bon c?ur et ses talents de... bibliothécaire !','','','',0,'','','m','0',7,'5 EUR','','',' kidnappant mlle labourdette ravissante bibliothecaire chef brigands ses quatre complices croient pouvoir obtenir municipalite rancon rondelette mais c est compter sans courage jeune fille son bon c ur ses talents bibliothecaire ',' enlevement bibliothecaire ','  L\'enlèvement de la bibliothécaire   ',1,'','2012-10-24 14:42:51','2012-10-24 13:53:38','0','','2002-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (88,'a','Des bibliothèques pleines de fantômes','','','',0,'',24,0,0,0,'2008','','','978-2-207-26054-8','1 vol. (138 p.)','couv. ill. en coul.','18 cm','','','','Avez-vous peur de mourir dans votre sommeil, enseveli sous l\'écroulement de votre bibliothèque ? L\'accumulation de livres ne met-elle pas en danger l\'existence même de votre famille ? Classez-vous les volumes par thème, langue, auteur, date de parution, format ou selon un autre critère de vous seul connu ? Peut-on faire voisiner sur une étagère deux auteurs irrémédiablement brouillés dans la vie ? Autant de graves questions se posant à cette espèce en voie de disparition : les bibliomanes, qui, outre la passion de posséder les livres, ont celle de les lire. Les bibliothèques sont des êtres vivants à l\'image de notre complexité intérieure. Elles finissent par composer un labyrinthe dont pour notre plus grand, et dangereux, plaisir nous pouvons très bien ne plus sortir. Dans ce petit traité sur l\'art de vivre avec trop de livres apparaissent, parmi nombre d\'autres, Pessoa tentant de devenir bibliothécaire, Matisse postulant au poste de «contrôleur du droit des pauvres» ou encore le capitaine Achab et le mystère de sa jambe abandonnée à Moby Dick. En fait, ces milliers de pages qui occupent nos étagères sont peuplées de fantômes bien vivants qui, une fois rencontrés, ne nous quittent plus.','','','Bibliothèques;Livres et lecture',3,'',' bibliotheques livres lecture ','m','0',7,'12 EUR','','',' avez vous peur mourir dans votre sommeil enseveli sous ecroulement votre bibliotheque accumulation livres ne met elle pas danger existence meme votre famille classez vous volumes par theme langue auteur date parution format ou selon autre critere vous seul connu peut on faire voisiner sur etagere deux auteurs irremediablement brouilles dans vie autant graves questions se posant cette espece voie disparition bibliomanes qui outre passion posseder livres ont celle lire bibliotheques sont etres vivants image notre complexite interieure elles finissent par composer labyrinthe dont pour notre plus grand dangereux plaisir nous pouvons tres bien ne plus sortir dans ce petit traite sur art vivre avec trop livres apparaissent parmi nombre autres pessoa tentant devenir bibliothecaire matisse postulant poste controleur droit pauvres ou encore capitaine achab mystere sa jambe abandonnee moby dick fait ces milliers pages qui occupent nos etageres sont peuplees fantomes bien vivants qui fois rencontres ne nous quittent plus ',' bibliotheques pleines fantomes ','  Des bibliothèques pleines de fantômes   ',1,'','2012-10-24 14:42:51','2012-10-24 13:52:55','0','','2008-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (89,'a','Cuisine actuelle de l\'Afrique noire','','','plus de 60 recettes faciles à réaliser',0,'',25,0,0,0,'2003','','','978-2-87691-819-1','215 p.','ill. en noir et en coul., couv. ill. en coul.','23 cm','','','','Présentation de l\'éditeur\r\nSénégal, Mali, Cameroun, Congo, Côte d\'Ivoire, logo, Nigeria, Gabon... L\'Afrique Noire, dans son immense diversité, offre aux palais amateurs de bonne chère, des plats savoureux et délicats qui, contrairement aux idées reçues, peuvent être simples à réaliser dès lors que l\'on dispose des connaissances et du savoir-faire indispensables. Plus de 60 recettes faciles à réaliser : A travers un large choix de recettes, composé entre autres des grands classiques (Tiep, Yassa, Mafé, Saka-Saka, Mbongo...), les auteurs de cet ouvrage nous accompagnent pas à pas pour réaliser le meilleur de la cuisine africaine. Présentation des ingrédients spécifiques à la préparation des plats (arachide, manioc, graines de courge...), portraits légendés, trucs et astuces, recettes étape par étape... dans ce beau livre riche en photos, la cuisine africaine se met enfin à la portée de fous ! Un beau livre de cuisine pour goûter et apprécier toutes les saveurs de l\'Afrique Noire : Et pour qu\'au plaisir de la bouche se joigne celui de l\'esprit et de la vue, des proverbes, des textes, des photos viennent agrémenter de-ci de-là les recettes.','','','Cuisine africaine',65,'',' cuisine africaine ','m','0',7,'24,90 EUR','','',' presentation editeur senegal mali cameroun congo cote ivoire logo nigeria gabon afrique noire dans son immense diversite offre palais amateurs bonne chere plats savoureux delicats qui contrairement idees recues peuvent etre simples realiser lors que on dispose connaissances savoir faire indispensables plus 60 recettes faciles realiser travers large choix recettes compose entre autres grands classiques tiep yassa mafe saka saka mbongo auteurs cet ouvrage nous accompagnent pas pas pour realiser meilleur cuisine africaine presentation ingredients specifiques preparation plats arachide manioc graines courge portraits legendes trucs astuces recettes etape par etape dans ce beau livre riche photos cuisine africaine se met enfin portee fous beau livre cuisine pour gouter apprecier toutes saveurs afrique noire pour qu plaisir bouche se joigne celui esprit vue proverbes textes photos viennent agrementer ci recettes ',' cuisine actuelle afrique noire plus 60 recettes faciles realiser ','  Cuisine actuelle de l\'Afrique noire   plus de 60 recettes faciles à réaliser',1,'','2012-10-24 14:42:51','2012-12-12 12:37:10','0','','2003-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (90,'a','Au coeur de l\'Afrique','','','',0,'',26,0,18,0,'2012','','Nouvelle éd.','978-2-7459-5517-3','1 vol. (251 p.)','ill. en noir et en coul., couv. ill. en coul.','27 cm','','','','Présentation de l\'éditeur\r\nUne plongée au coeur de l\'Afrique, mère de l\'humanité et continent phare du IIIe millénaire. Face aux visions d\'une Afrique déchirée, voici de nouveaux éclairages. A travers des questions comme la désertification, la déforestation, l\'exode rural, la colonisation ou l\'explosion démographique, le continent se livre en profondeur. Sa géographie a été une donnée décisive, ses peuples se sont adaptés à une nature difficile. L\'Afrique, c\'est une histoire remplie d\'épisodes épiques d\'une richesse insoupçonnée, assombrie parla terrible période de l\'esclavage. C\'est aussi une leçon de courage et de solidarité inépuisables. ','','','Afrique noire;Géographie;Ouvrages pour la jeunesse;Histoire',92,'',' afrique noire geographie ouvrages pour jeunesse histoire ','m','0',8,'14,50 EUR','','',' presentation editeur plongee coeur afrique mere humanite continent phare iiie millenaire face visions afrique dechiree voici nouveaux eclairages travers questions comme desertification deforestation exode rural colonisation ou explosion demographique continent se livre profondeur sa geographie ete donnee decisive ses peuples se sont adaptes nature difficile afrique c est histoire remplie episodes epiques richesse insoupconnee assombrie parla terrible periode esclavage c est aussi lecon courage solidarite inepuisables ',' coeur afrique ','  Au coeur de l\'Afrique   ',1,'','2012-10-24 14:42:51','2012-12-12 12:26:31','0','','2012-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
