INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (113,'g','Les noces funèbres','','','',0,'',40,0,0,0,'2008','','','','1 DVD zone 2 (1 h 17 min)','19/9, coul. (PAL), son., surround (Dolby)','','','','','Synopsis\r\nAu XIXe siècle, dans un village d\'Europe de l\'est, Victor, un jeune homme, découvre le monde des morts après avoir épousé, sans le vouloir, le cadavre d\'une mystérieuse mariée. Pendant son voyage, sa promise, Victoria l\'attend désespérément dans le monde des vivants. Bien que la vie au Royaume des Morts s\'avère beaucoup plus animée et joyeuse que sa véritable existence, Victor apprend que rien au monde, pas même la mort, ne pourra briser son amour pour sa femme... ','','','',0,'','','m','0',1,'','','',' synopsis xixe siecle dans village europe est victor jeune homme decouvre monde morts apres avoir epouse sans vouloir cadavre mysterieuse mariee pendant son voyage sa promise victoria attend desesperement dans monde vivants bien que vie royaume morts s avere beaucoup plus animee joyeuse que sa veritable existence victor apprend que rien monde pas meme mort ne pourra briser son amour pour sa femme ',' noces funebres ','  Les noces funèbres   ',1,'','2012-10-24 14:57:40','2012-12-12 14:03:11','0',0x687474703A2F2F6563782E696D616765732D616D617A6F6E2E636F6D2F696D616765732F492F353172676F305930666F4C2E5F41413136305F2E6A7067,'2008-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
