INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (122,'a','N° 393 - novembre 2011 - L\'Île de Pâques',NULL,'','Le rêve ultime des voyageurs',0,'',0,0,0,0,'2011',NULL,'','','','','','','','ÉVASION - La dernière frontière du Pacifique\r\nÀ des milliers de kilomètres de toute terre émergée, l’île de Pâques et ses statues géantes fascinent toujours les voyageurs.\r\n\r\nMODES DE VIE - Le Grand Paris\r\nÀ quoi ressemblera le Grand Paris ? Un métro de 200 kilomètres, un port gigantesque à Achères, une Silicon Valley à Saclay… La future mégapole commence à dévoiler son nouveau visage.\r\n\r\nENVIRONNEMENT - L\'iPhone est-il écolo ?\r\nÉtape par étape, l’analyse de l’impact environnemental du petit bijou d’Apple.\r\n\r\nVOYAGE - La nouvelle vie de Cracovie\r\nLa cité polonaise est l’un des lieux les plus touristiques de l’ancien bloc de l’Est. Grâce à sa richesse culturelle et à sa jeunesse qui crée une ambiance de «movida».\r\n\r\nPARTIR - Quoi de neuf à Bruxelles ?\r\nMalgré la crise institutionnelle qui paralyse le pays, la capitale belge n’a pas perdu sa créativité. Tables, hôtels, shopping… Tour d’horizon des nouvelles adresses.\r\n\r\nGÉOPOLITIQUE - Comment la Chine redessine le monde\r\nEn Grèce, en Birmanie, en Zambie… Partout, les Chinois financent et bâtissent des ports, des routes, des hôpitaux. C’est la phase nouvelle du «zouchuqu», leur stratégie de conquête tous azimuts.\r\n\r\nLE MONDE EN CARTES - Pourquoi la Kapisa est dans l’oeil du cyclone ?\r\nProche de Kaboul, cette province est la zone de tous les dangers pour les militaires français.\r\n\r\nGRANDE SÉRIE : LE LITTORAL FRANÇAIS - LA NORMANDIE\r\nNotre photographe livre son coup d’oeil sur les hauts lieux de la côte normande. Et notre journaliste analyse les enjeux du moment sur le plan du tourisme et de l’environnement. ','','','','',0,'','','b','2',1,'','',' evasion derniere frontiere pacifique milliers kilometres toute terre emergee ile paques ses statues geantes fascinent toujours voyageurs modes vie grand paris quoi ressemblera grand paris metro 200 kilometres port gigantesque acheres silicon valley saclay future megapole commence devoiler son nouveau visage environnement iphone est il ecolo etape par etape analyse impact environnemental petit bijou apple voyage nouvelle vie cracovie cite polonaise est lieux plus touristiques ancien bloc est grace sa richesse culturelle sa jeunesse qui cree ambiance movida partir quoi neuf bruxelles malgre crise institutionnelle qui paralyse pays capitale belge n pas perdu sa creativite tables hotels shopping tour horizon nouvelles adresses geopolitique comment chine redessine monde grece birmanie zambie partout chinois financent batissent ports routes hopitaux c est phase nouvelle zouchuqu leur strategie conquete tous azimuts monde cartes pourquoi kapisa est dans oeil cyclone proche kaboul cette province est zone tous dangers pour militaires francais grande serie littoral francais normandie notre photographe livre son coup oeil sur hauts lieux cote normande notre journaliste analyse enjeux moment sur plan tourisme environnement ','',' n 393 novembre 2011 ile paques reve ultime voyageurs ','  N° 393 - novembre 2011 - L\'Île de Pâques   Le rêve ultime des voyageurs',1,'','2012-10-24 17:26:11','2012-11-20 08:29:44','0',,'2011-11-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (123,'a','N° 402 - août 2012 - Compostelle, Shikoku, Lalibela... Les chemins de la sagesse',NULL,'','',0,'',0,0,0,0,'2012',NULL,'','','','','','','','LE MONDE QUI CHANGE\r\nLe patrimoine de la Syrie sous la menace.\r\n\r\nLES HÉROS D\'AUJOURD\'HUI\r\nCe chirurgien indien qui prend à cœur la santé de son pays.\r\n\r\nLE GOÛT DE GEO\r\nLe «dim-sum», un microfestin à la chinoise.\r\n\r\nÉVASION - Dans le sillage d\'Ulysse\r\nHeureux qui comme le héros d\'Homère a fait un beau voyage... GEO a suivi ses pas en Méditerranée.\r\n\r\nESCALE - Jean Didier Urbain\r\nVite parcouru, mal lu.\r\n\r\nMODES DE VIE - A la vie, à la mer\r\nReportage sur ces marins pêcheurs qui écument les océans glacés et bravent les tempêtes.\r\n\r\nENVIRONNEMENT - Faut-il se préparer aux grandes sécheresses ?\r\nIl fait plus sec et plus chaud. Résultat, la terre a soif et les agriculteurs trinquent.\r\n\r\nVOYAGE - Le renouveau des chemins sacrés\r\nLes marcheurs affluent vers les routes spirituelles à la recherche du grand voyage intérieur.\r\n\r\nLE BON PLAN - Le Bilbao des Bilbotars\r\n\r\nGÉOPOLITIQUE - Terres fertiles à louer\r\nDe puissants investisseurs étrangers trustent les meilleurs champs des pays du Sud. Néocolonialisme ou développement agricole ?\r\n\r\nLE MONDE EN CARTES - Des îles très disputées\r\n\r\nGRANDE SÉRIE - La France des villages\r\nPérigord et Quercy : panorama mensuel des pépites du terroir.','','','','',0,'','','b','2',1,'','',' monde qui change patrimoine syrie sous menace heros aujourd hui ce chirurgien indien qui prend coeur sante son pays gout geo dim sum microfestin chinoise evasion dans sillage ulysse heureux qui comme heros homere fait beau voyage geo suivi ses pas mediterranee escale jean didier urbain vite parcouru mal lu modes vie vie mer reportage sur ces marins pecheurs qui ecument oceans glaces bravent tempetes environnement faut il se preparer grandes secheresses il fait plus sec plus chaud resultat terre soif agriculteurs trinquent voyage renouveau chemins sacres marcheurs affluent vers routes spirituelles recherche grand voyage interieur bon plan bilbao bilbotars geopolitique terres fertiles louer puissants investisseurs etrangers trustent meilleurs champs pays sud neocolonialisme ou developpement agricole monde cartes iles tres disputees grande serie france villages perigord quercy panorama mensuel pepites terroir ','',' n 402 aout 2012 compostelle shikoku lalibela chemins sagesse ','  N° 402 - août 2012 - Compostelle, Shikoku, Lalibela... Les chemins de la sagesse   ',1,'','2012-10-24 17:30:07','2012-11-20 08:29:44','0',0x687474703A2F2F7777772E67656F2E66722F7661722F67656F2F73746F726167652F696D616765732F6D656469612F636F75766572747572652D67656F2D6E2D3430322F313133353938332D312D6672652D46522F636F75766572747572652D67656F2D6E2D3430325F363230783436352E6A7067,'2012-08-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (124,'l','Bulletin des bibliothèques de France',NULL,'BBF','',0,'',48,0,0,0,'1995-',NULL,'','1292-8399',NULL,NULL,NULL,NULL,'','','','http://bbf.enssib.fr/','','',0,'','','s','1',1,'','','','',' bulletin bibliotheques france bbf ','  Bulletin des bibliothèques de France  BBF ',1,'','2012-10-24 17:35:46','2012-11-20 08:29:44','0',0x687474703A2F2F6262662E656E737369622E66722F73697465732F6262662E656E737369622E66722F7468656D65732F4242462F696D616765732F636F6D6D756E2F4242665F6C6F676F5F696D7072657373696F6E2E706E67,'1995-01-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (125,'l','Bibliothécaire de soi-même',NULL,'','',0,'',0,0,0,0,'2010',NULL,'','','',NULL,NULL,NULL,'','','Les bibliothèques publiques ont souvent pour origine des collections privées. Mais la fréquentation de ces bibliothèques n\'empêche pas, accompagne même, le goût pour constituer sa bibliothèque privée, « la reconstitution à son usage propre d\'une sorte de bibliothèque publique ». La gestion de ces bibliothèques privées se heurte aux mêmes problèmes que les bibliothèques institutionnelles, comme le classement, le rangement, mais aussi la politique d\'acquisition, même si le caractère privé de sa bibliothèque autorise de nombreuses licences au propriétaire des livres, « bibliothécaire de soi-même ». L\'obligation de conservation et d\'entretien est évidente, si celle de désherbage, désormais largement pratiqué dans les bibliothèques publiques, l\'est moins - tout comme le catalogage, et a fortiori le prêt.','','','',0,'','','a','2',1,'','','',' bibliotheques publiques ont souvent pour origine collections privees mais frequentation ces bibliotheques n empeche pas accompagne meme gout pour constituer sa bibliotheque privee reconstitution son usage propre sorte bibliotheque publique gestion ces bibliotheques privees se heurte memes problemes que bibliotheques institutionnelles comme classement rangement mais aussi politique acquisition meme si caractere prive sa bibliotheque autorise nombreuses licences proprietaire livres bibliothecaire soi meme obligation conservation entretien est evidente si celle desherbage desormais largement pratique dans bibliotheques publiques est moins tout comme catalogage fortiori pret ',' bibliothecaire soi meme ','  Bibliothécaire de soi-même   ',1,'','2012-10-24 17:41:02','2012-12-12 15:24:55','',0x687474703A2F2F6262662E656E737369622E66722F73697465732F6262662E656E737369622E66722F7468656D65732F4242462F696D616765732F636F6D6D756E2F4242665F6C6F676F5F696D7072657373696F6E2E706E67,'2010-11-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (126,'l','Voyages en BM',NULL,'','',0,'',0,0,0,0,'2010',NULL,'','','',NULL,NULL,NULL,'','','La trajectoire d\'un usager des bibliothèques publiques, de l\'enfance à aujourd\'hui : autodidacte, il fréquente assidûment la bibliothèque municipale de Montreuil-sous-Bois, « copropriétaire d\'une BM unique dans la commune... Ma première patrie fut cette bibliothèque » ; le contact permanent des livres, le passage difficile de l\'adolescence, puis le « boulot d\'auteur », toujours accompagné des bibliothèques. « Aujourd\'hui, je ne ressemble pas à mes gosses. À cause ou grâce à ces livres empruntés chaque semaine, j\'ai quitté une classe sociale... sans jamais en trouver une autre de rechange. »','','','',0,'','','a','2',1,'','','',' trajectoire usager bibliotheques publiques enfance aujourd hui autodidacte il frequente assidument bibliotheque municipale montreuil sous bois coproprietaire bm unique dans commune ma premiere patrie fut cette bibliotheque contact permanent livres passage difficile adolescence puis boulot auteur toujours accompagne bibliotheques aujourd hui je ne ressemble pas mes gosses cause ou grace ces livres empruntes chaque semaine j ai quitte classe sociale sans jamais trouver autre rechange ',' voyages bm ','  Voyages en BM   ',1,'','2012-10-24 17:44:30','2012-11-20 08:29:44','0',0x687474703A2F2F6262662E656E737369622E66722F73697465732F6262662E656E737369622E66722F7468656D65732F4242462F696D616765732F636F6D6D756E2F4242665F6C6F676F5F696D7072657373696F6E2E706E67,'2010-11-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, opac_serialcirc_demande, num_notice_usage, is_numeric) VALUES (127,'l','L\'abeille et le bibliothécaire ou éthique du libre et lecture publique en zone rurale',NULL,'','',0,'',0,0,0,0,'2012',NULL,'','','',NULL,NULL,NULL,'','','Mariant évolution des techniques et analyse des territoires ruraux, cet article se veut une réflexion (et une incitation) sur le travail en commun, une « théorie de la pratique », la mise en oeuvre professionnelle et partagée de la société de la connaissance. L\'exemple du RISOM (Réseau intercommunal et solidaire des médiathèques de Tence, St-Jeures et Le Mazet-St-Voy, Haute-Loire), qui propose le partage d\'informations sur des projets d\'animation, leurs outils et leurs usages, vient à l\'appui et en illustration de cette analyse.','','','',0,'','','a','2',1,'','','',' mariant evolution techniques analyse territoires ruraux cet article se veut reflexion incitation sur travail commun theorie pratique mise oeuvre professionnelle partagee societe connaissance exemple risom reseau intercommunal solidaire mediatheques tence st jeures mazet st voy haute loire qui propose partage informations sur projets animation leurs outils leurs usages vient appui illustration cette analyse ',' abeille bibliothecaire ou ethique libre lecture publique zone rurale ','  L\'abeille et le bibliothécaire ou éthique du libre et lecture publique en zone rurale   ',1,'','2012-10-24 17:48:22','2012-12-12 12:21:10','',0x687474703A2F2F6262662E656E737369622E66722F73697465732F6262662E656E737369622E66722F7468656D65732F4242462F696D616765732F636F6D6D756E2F4242665F6C6F676F5F696D7072657373696F6E2E706E67,'2012-09-01',1,'',0,0,0,'',0,'0000-00-00 00:00:00',1,0,0);
