INSERT INTO parametres (id_param, type_param, sstype_param, valeur_param, comment_param, section_param, gestion) VALUES (1164,'empr','sms_msg_animation','Bonjour,\nUne nouvelle réservation d\'animation a été effectuée.\nConsultez votre compte!','Texte du sms envoyé lors de l\'inscription à une animation \n !!animation_name!! : Nom de l\'animation \n !!animation_empr_name!! : Nom de l\'emprunteur \n !!animation_empr_firstname!! : Prénom de l\'emprunteur \n !!animation_start_date!! : Date de départ de l\'animation \n !!animation_end_date!! : Date de fin de l\'animation \n !!animation_start_hour!! : Heure de départ de l\'animation \n !!animation_end_hour!! : Heure de fin de l\'animation \n !!animation_location!! : Localisation(s) de l\'animation \n','',0);
