INSERT INTO parametres (id_param, type_param, sstype_param, valeur_param, comment_param, section_param, gestion) VALUES (1167,'dsi','notice_group_by_default','','Grouper les notices au sein de la bannette, information à séparer par des virgules : \n 1er : f pour facette ou cp pour champ perso (fonctionnement PMB 5) \n 2ème : Id de la facette ou du champ perso \n 3ème - Id du sous champ (0 si aucun) \n 4ème - Ordre asc, desc \n 5ème - Type de données de tri (alpha, num, date) \n\n 4 et 5 sont obligatoires pour les facettes \n\n Exemple : f,1,0,asc,alpha','',0);
